const $=s=>document.querySelector(s),E=FluxEngine;
const roles={mechanic:'Mécanicien',owner:'Responsable',recycler:'Recycleur'},faultLabels={none:'Aucun',minor:'Mineur',major:'Majeur',critical:'Critique'};
const orientationLabel=code=>E.orientationInfo[code]?.label||code;
const frenchText=value=>String(value??'').replace(/\b(Original|Waste|Oriented|Reuse|Remanufacture|Repurpose|Recycle|none|minor|major|critical)\b/g,code=>({Original:'En service',Waste:'Hors d’usage',Oriented:'Orientation validée',none:'aucun',minor:'mineur',major:'majeur',critical:'critique'}[code]||orientationLabel(code)));
const journeyPositions=new Map();
let db,role='mechanic',user=null,view='passport',selected=new URLSearchParams(location.search).get('battery')||'BP-004',weights={...E.defaults};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const current=()=>db.batteries.find(b=>b.id===selected)||db.batteries[0];
const pending=b=>(b.requests||[]).find(r=>r.state==='PENDING');
const canDecide=b=>role==='recycler'&&b.stage>=4&&b.inspected&&!!b.inspection;
const defaultView=()=>role==='owner'?'inbox':'passport';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
async function request(url,body){const r=await fetch(url,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok){const e=Error(d.error||'Erreur serveur');e.status=r.status;throw e;}return d;}
async function loadState(){const d=await request('/api/state');db=d;role=d.role;user=d.user;$('.live').textContent='● Connexion active';$('.sidefoot p').textContent='Les étapes et les demandes sont enregistrées dans le passeport.';$('.role').firstChild.textContent='Compte connecté ';}
async function mutate(action,payload={}){const b=current();try{await request('/api/batteries/'+b.id+'/'+action,{...payload,revision:b.revision});await loadState();if(action==='inspection')view='decision';else if(role==='owner'&&['waste','refuse'].includes(action))view='inbox';render();toast({diagnostic:'Demande envoyée au responsable. Le statut reste En service.',waste:'Demande validée : statut Hors d’usage et destination enregistrés.',refuse:'Demande refusée : le statut reste En service.',receive:'Réception confirmée.',inspection:'Inspection enregistrée. Vous pouvez comparer les orientations.',decision:'Décision enregistrée dans le graphe.'}[action]||'Suivi mis à jour.');}catch(e){toast(e.message);if(e.status===401)login(role);}}
function badge(b,big=false){return `<span class="badge ${b.status==='Waste'?'warn':''} ${big?'big-status':''}">${esc(frenchText(b.status))}</span>`;}
function render(){if(!db)return;$('#scan-open').hidden=role==='owner';$('#export').hidden=false;if(!db.batteries.length){renderEmpty();return;}const b=current();selected=b.id;
 if(view==='decision'&&role!=='recycler')view=defaultView();if(view==='inbox'&&role!=='owner')view='passport';
 document.querySelector('[data-view="inbox"]').hidden=role!=='owner';document.querySelector('[data-view="decision"]').hidden=role!=='recycler';
 document.querySelectorAll('nav button').forEach(el=>el.classList.toggle('active',el.dataset.view===view));$('#role').value=role;$('#role').disabled=false;$('#role').title='Changer de compte';
 const names={inbox:'Demandes reçues',passport:'Passeport',history:'Suivi',decision:'Aide à la décision'};$('#breadcrumb').textContent=names[view];
 const title=view==='history'?'Le suivi de la batterie':view==='decision'?'Choisir la prochaine vie':view==='inbox'?'Demandes des garages':{mechanic:'Diagnostic et signalement',owner:'Validation du responsable',recycler:'Réception et inspection'}[role];
 $('#title').textContent=b.stage===5&&view==='passport'?'Orientation validée':title;$('#subtitle').textContent=view==='history'?'Les étapes et les interventions restent consultables.':view==='decision'?'Votre inspection alimente une recommandation expliquée.':{mechanic:'Consultez le passeport puis signalez vos constats au responsable.',owner:'Examinez les motifs et choisissez une destination agréée avant validation.',recycler:'Vérifiez le statut puis inspectez les modules avant toute décision.'}[role];
 if(b.stage===5&&view==='passport')$('#subtitle').textContent='Le parcours de décision est terminé. Retrouvez les interventions dans le suivi.';
 $('#eyebrow').textContent={mechanic:'ESPACE GARAGISTE · LECTURE DU PASSEPORT',owner:'ESPACE CONSTRUCTEUR · DEMANDES ET SUIVI',recycler:'ESPACE CENTRE DE TRI · RÉCEPTION ET INSPECTION'}[role];
 $('#notification-count').textContent=String(db.notifications?.length||0);$('#stats').hidden=role==='mechanic';$('#stats').innerHTML=role==='owner'?stats([['Demandes en attente',db.notifications.length],['Batteries hors d’usage',db.batteries.filter(x=>x.status==='Waste').length]]):stats([['À réceptionner',db.batteries.filter(x=>x.stage===3&&x.status==='Waste').length],['À inspecter',db.batteries.filter(x=>x.stage===4&&!x.inspected).length]]);
 const q=$('#search').value.toLowerCase(),found=db.batteries.filter(x=>(x.id+x.model+x.owner).toLowerCase().includes(q));$('#resultcount').textContent=found.length+' passeport'+(found.length>1?'s':'');
 $('#fleet').innerHTML=found.map(x=>`<button class="batteryitem ${x.id===b.id?'selected':''}" data-id="${x.id}"><strong>${esc(x.model)}</strong><small>${x.id} · SOH ${x.soh} %</small><br>${badge(x)}${pending(x)?'<span class="badge notice">Demande en attente</span>':''}</button>`).join('')||'<p>Aucun passeport trouvé.</p>';
 $('#content').innerHTML=view==='inbox'?inbox():view==='history'?historyView(b):view==='decision'?decisionView(b):passportView(b);bind();
}
function renderEmpty(){
 $('#role').value=role;$('#role').disabled=false;$('#export').hidden=true;$('#scan-open').hidden=role==='owner';$('#stats').hidden=true;$('#fleet').innerHTML='';$('#resultcount').textContent='0 passeport';$('#breadcrumb').textContent=role==='owner'?'Demandes reçues':'Scan du passeport';$('#eyebrow').textContent='BATTERY PASSPORT';$('#title').textContent=role==='mechanic'?'Tout commence par un scan':role==='owner'?'Demandes des garages':'Consulter un passeport';$('#subtitle').textContent=role==='mechanic'?'Scannez le QR imprimé pour ajouter une batterie au statut En service.':role==='owner'?'Les signalements apparaîtront après l’ajout et le diagnostic du mécanicien.':'Scannez le QR d’une batterie déjà enregistrée par le mécanicien.';
 document.querySelector('[data-view="inbox"]').hidden=role!=='owner';document.querySelector('[data-view="decision"]').hidden=role!=='recycler';$('#notification-count').textContent='0';$('#content').innerHTML='<div class="card"><h2>Aucun passeport enregistré</h2><p>'+ (role==='mechanic'?'Utilisez le bouton Scanner un QR code pour lire les informations, les vérifier puis ajouter le passeport.':role==='owner'?'Aucune demande à traiter pour le moment.':'Le mécanicien doit d’abord ajouter le passeport de la batterie.')+'</p></div>';
}
function stats(items){return items.map(([label,value])=>`<div class="stat"><small>${label}</small><strong>${value}</strong></div>`).join('');}
function summary(b){return `<div class="card"><div class="cardtop"><div><div class="label">PASSEPORT ${b.id}</div><h2>${esc(b.model)}</h2><p class="muted">${esc(b.serial)} · ${esc(b.manufacturer)}</p></div>${badge(b)}</div><div class="metrics"><div><span class="label">SOH</span><strong>${b.soh} %</strong></div><div><span class="label">Chimie</span><strong>${b.chemistry}</strong></div><div><span class="label">Âge</span><strong>${b.age} ans</strong></div></div><div class="facts"><div><span class="label">Responsable du passeport</span><span>${esc(b.owner)}</span></div><div><span class="label">Cycles · capacité</span><span>${b.cycles} cycles · ${b.capacity} kWh</span></div></div><p class="small readonly-note">Données du passeport en lecture seule.</p></div>`;}
function tracking(b){
 const completed=b.stage===5;
 const steps=[['En service',true],['Signalé',b.stage>=1],['Hors d’usage',b.stage>=2],['Destination',!!b.transfer],['Reçu',b.stage>=4],['Inspecté',!!b.inspected],['Décision',completed]];
 const active=completed?6:b.inspected?5:b.stage>=4?4:b.transfer?3:b.stage>=2?2:b.stage>=1?1:0;
 const position=active/6*100,previous=journeyPositions.get(b.id)??position;journeyPositions.set(b.id,position);
 return `<div class="card"><h3>Suivi du parcours</h3><div class="journey" aria-label="Étape ${active+1} sur 7 : ${steps[active][0]}"><div class="journey-road" style="--progress:${position}%;--previous:${previous}%"><i class="journey-progress"></i><span class="journey-car" aria-hidden="true"><svg viewBox="0 0 32 14" fill="none"><path d="M1 8 12 2h7l12 6v4H1Z" fill="#a9b3bf" stroke="#314d6e" stroke-width=".8" stroke-linejoin="round"/><path d="m6 7 7-4h5l8 4Z" fill="#20374e"/><path d="M18 3v4M2 8h28" stroke="#dce4eb" stroke-width=".7"/><path d="M29 8h2" stroke="#f3fafc" stroke-width="1.2"/><circle cx="7" cy="11" r="2.6" fill="#142b43"/><circle cx="25" cy="11" r="2.6" fill="#142b43"/><circle cx="7" cy="11" r="1" fill="#b9c5d1"/><circle cx="25" cy="11" r="1" fill="#b9c5d1"/></svg></span></div><div class="journey-labels">${steps.map(([label,done],i)=>`<span class="${done?'done':''} ${i===active?'current':''}">${label==='En service'?'En<br>service':label==='Hors d’usage'?'Hors<br>d’usage':label==='Destination'?'Centre<br>de tri':label}</span>`).join('')}</div></div>${b.transfer?`<p class="small">Destination : <b>${esc(b.transfer.destination)}</b>${b.stage>=4?' · Réception confirmée':' · En attente de réception'}</p>`:''}${completed?'<div class="tip"><b>Orientation validée · parcours de décision terminé.</b><br>La décision est enregistrée. Le traitement physique de la batterie reste à réaliser par la filière retenue.</div>':''}<button class="outline" data-go="history">Consulter l’historique</button></div>`;
}
function mechanicAction(b){const r=pending(b);if(r)return `<div class="card"><h3>Signalement transmis</h3><span class="badge notice">En attente du responsable</span><p>${esc(r.note)}</p><p class="small">Le passeport reste En service jusqu’à la validation du responsable.</p></div>`;
 if(b.stage===5)return '<div class="card"><h3>Parcours de décision terminé</h3><p>Le centre de tri a enregistré son orientation. Consultez le suivi pour retrouver les interventions.</p></div>';
 if(b.status!=='Original')return `<div class="card"><h3>Signalement traité</h3><p>Le responsable a validé le statut Hors d’usage. Consultez le suivi pour connaître l’avancement.</p></div>`;
 const refusal=(b.requests||[]).findLast(x=>x.state==='REJECTED');return `<div class="card"><h3>Signaler une batterie hors d’usage</h3>${refusal?`<div class="alert danger"><b>Le précédent signalement a été refusé.</b><p>${esc(refusal.refusalReason)}</p></div>`:''}<form id="signal"><label>Diagnostic / motif<textarea name="note" required maxlength="1000" placeholder="Décrivez les anomalies constatées et le motif du signalement…"></textarea></label><p class="small">Cette action crée une demande au responsable. Elle ne modifie ni les mesures ni le statut du passeport.</p><button class="primary">Signaler hors d’usage</button></form></div>`;}
function centerSelect(){return `<label>Centre de tri de destination<select name="centerId"><option value="">Choisir un centre agréé</option>${db.centers.map(c=>`<option value="${c.id}">${esc(c.name)} — ${esc(c.city)} · Agréé</option>`).join('')}</select></label>`;}
function ownerAction(b){if(b.stage===5)return '<div class="card"><h3>Parcours de décision terminé</h3><p>Le centre de tri a validé une orientation. Le suivi complet reste consultable.</p><button class="outline" data-go="history">Consulter le suivi</button></div>';const r=pending(b);if(r)return `<div class="card"><div class="label">DEMANDE ${esc(r.id.slice(0,8))}</div><h3>${esc(r.garageName)} demande En service → Hors d’usage</h3><div class="request-note"><b>Motif du garage</b><p>${esc(r.note)}</p><span class="small">${date(r.at)}</span></div><form id="owner-decision" data-request-id="${r.id}">${centerSelect()}<label>Motif en cas de refus<textarea name="refusalReason" maxlength="1000" placeholder="Expliquez pourquoi vous refusez cette demande…"></textarea></label><div class="actions"><button class="primary" name="action" value="waste">Valider et passer en Hors d’usage</button><button class="outline" name="action" value="refuse">Refuser</button></div></form></div>`;
 if(b.status==='Waste'&&(b.stage===2||(b.stage===3&&!b.transfer?.approved)))return `<div class="card"><h3>Confirmer une destination agréée</h3><p>Le statut Hors d’usage est déjà enregistré. Complétez la destination de ce dossier existant.</p><form id="legacy-transfer">${centerSelect()}<button class="primary">Confirmer la destination</button></form></div>`;
 return `<div class="card"><h3>${b.status==='Waste'?'Demande déjà traitée':'Aucune demande en attente'}</h3><p class="muted">${b.status==='Waste'?'Le statut est validé. Le centre de tri poursuit le parcours.':'Le mécanicien peut transmettre un signalement depuis son espace.'}</p><button class="outline" data-go="inbox">Voir les demandes reçues</button></div>`;}
function inbox(){const cards=db.notifications.map(r=>`<article class="card notification-card"><div><span class="badge notice">À examiner</span><h3>${esc(r.garageName)} demande En service → Hors d’usage pour ${r.batteryId}</h3><p>${esc(r.note)}</p><span class="small">${esc(r.model)} · ${date(r.at)}</span></div><button class="primary" data-review="${r.batteryId}">Examiner la demande</button></article>`).join('');const answered=db.batteries.flatMap(b=>(b.requests||[]).filter(r=>r.state!=='PENDING').map(r=>({...r,batteryId:b.id}))).sort((a,b)=>String(b.decidedAt).localeCompare(String(a.decidedAt)));
 return `<section><h2>${db.notifications.length} demande${db.notifications.length>1?'s':''} en attente</h2>${cards||'<div class="card"><p class="muted">Aucun signalement en attente. Les nouvelles demandes des garages apparaîtront ici.</p></div>'}${answered.length?`<div class="card"><h3>Dernières réponses</h3>${answered.map(r=>`<div class="answered"><span class="badge ${r.state==='REJECTED'?'red':''}">${r.state==='APPROVED'?'Validée':'Refusée'}</span> <b>${r.batteryId}</b><p>${esc(r.state==='REJECTED'?r.refusalReason:r.note)}</p><small class="muted">${date(r.decidedAt)}</small></div>`).join('')}</div>`:''}</section>`;}
function recyclerAction(b){if(b.stage===5)return `<div class="card"><div class="status-hero">${badge(b,true)}</div><h3>${esc(orientationLabel(b.decision.orientation))}</h3><p>${esc(E.orientationInfo[b.decision.orientation]?.description)}</p><p>${esc(b.decision.justification)}</p><div class="tip"><b>Prochaine action</b><br>${esc(E.orientationInfo[b.decision.orientation]?.next)}</div><button class="primary" data-go="decision">Consulter la décision</button></div>`;if(b.status!=='Waste')return `<div class="card"><div class="status-hero">${badge(b,true)}<span>Statut du passeport</span></div><div class="alert danger"><b>Réception bloquée</b><p>Le passeport est encore En service. Le responsable doit valider le passage en Hors d’usage.</p></div><button class="primary" disabled>Confirmer la réception</button></div>`;
 if(b.stage<4)return `<div class="card"><div class="status-hero">${badge(b,true)}<span>Statut du passeport vérifié</span></div>${b.stage===3&&b.transfer?`<p>Destination : ${esc(b.transfer.destination)}</p><button class="primary" data-action="receive">Confirmer la réception</button>`:'<div class="alert danger">Le responsable doit encore confirmer la destination agréée.</div>'}</div>`;

 if(b.inspected&&b.inspection)return `<div class="card"><div class="label">DÉFI 03 · AIDE À LA DÉCISION</div><h3>Inspection enregistrée</h3><p>Comparez les quatre orientations et consultez les explications avant de valider votre décision.</p><button class="primary" data-go="decision">Voir les conseils du Défi 03</button><details><summary>Revoir ou compléter l’inspection</summary>${inspectionForm(b)}</details></div>`;
 return `<div class="card"><span class="badge">Réception confirmée</span><h3>Inspection visuelle et technique</h3><p class="muted">Les données du passeport sont déjà renseignées. Ajoutez vos constats sur les cinq modules.</p>${inspectionForm(b)}</div>`;}
function inspectionForm(b){const modules=b.inspection?.modules||b.modules.map(m=>({...m,healthy:m.fault==='none'}));return `<form id="inspection"><div class="formgrid"><label>Chimie<input readonly value="${b.chemistry}"></label><label>Âge<input readonly value="${b.age} ans"></label><label>Cycles<input readonly value="${b.cycles}"></label><label>SOH du pack<input readonly value="${b.soh} %"></label></div><div class="module-inspections">${modules.map((m,i)=>`<fieldset><legend>Module ${i+1} · SOH ${m.soh} % · ${m.resistance} mΩ</legend><label class="check-label"><input type="checkbox" name="m${i}healthy" ${m.healthy?'checked':''} data-healthy="${i}"> Module sain</label><label>Défaut constaté<select name="m${i}fault">${Object.entries(faultLabels).map(([k,label])=>`<option value="${k}" ${m.fault===k?'selected':''}>${label}</option>`).join('')}</select></label><label>Constat visuel<input name="m${i}visual" required maxlength="200" value="${esc(m.visual)}" placeholder="État du boîtier, anomalies visibles…"></label></fieldset>`).join('')}</div><label>Conclusion de l’inspection<textarea name="note" required maxlength="1000">${esc(b.inspection?.note||'Inspection visuelle et technique des cinq modules effectuée.')}</textarea></label><button class="primary">Enregistrer l’inspection et comparer les orientations</button></form>`;}
function passportView(b){const action=role==='mechanic'?mechanicAction(b):role==='owner'?ownerAction(b):recyclerAction(b);return `<div class="grid"><section>${summary(b)}${action}${role==='owner'?'<div class="card management"><h3>Gestion du passeport</h3><p class="small">Suppression définitive de la batterie et de son historique.</p><button class="outline danger-button" data-delete>Supprimer la batterie</button></div>':''}</section><section>${tracking(b)}<div class="card"><h3>Défi 02 · Derniers événements</h3>${timeline(b,3)}</div></section></div>`;}
function date(v){return v?new Date(v).toLocaleString('fr-FR'):'—';}
function timeline(b,n=100){return b.events.slice(-n).reverse().map(e=>`<div class="event"><strong>${esc(frenchText(e.title))}</strong><p>${esc(frenchText(e.detail))}</p><time>${date(e.at)} · ${esc(e.actor)}</time></div>`).join('');}
function historyView(b){return `<div class="grid"><section>${summary(b)}<div class="card"><h3>Historique des interventions</h3>${timeline(b)}</div></section><section>${tracking(b)}<div class="card"><h3>Demandes du garage</h3>${(b.requests||[]).slice().reverse().map(r=>`<div class="answered"><span class="badge ${r.state==='REJECTED'?'red':r.state==='PENDING'?'notice':''}">${{PENDING:'En attente',APPROVED:'Validée',REJECTED:'Refusée'}[r.state]}</span><p>${esc(r.note)}</p>${r.refusalReason?`<p>Motif du refus : ${esc(r.refusalReason)}</p>`:''}<small class="muted">${date(r.at)}</small></div>`).join('')||'<p class="muted">Aucun signalement enregistré.</p>'}</div></section></div>`;}
function decisionData(b){const data={...b,...b.inspection.metrics,modules:b.inspection.modules};const levels=['none','minor','major','critical'];data.fault=[b.fault,...data.modules.map(m=>m.fault)].reduce((a,c)=>levels.indexOf(c)>levels.indexOf(a)?c:a,'none');return data;}
function decisionView(b){if(role!=='recycler')return '';if(!canDecide(b))return `<div class="card decision-locked"><div class="label">DÉFI 03 · AIDE À LA DÉCISION</div><h2>Préparer la prochaine vie</h2><p>Les quatre scores et leurs explications seront disponibles après votre inspection.</p><div class="flow"><div class="step ${b.status==='Waste'?'done':''}">Statut Hors d’usage validé</div><div class="step ${b.stage>=4?'done':''}">Réception confirmée</div><div class="step ${b.inspected?'done':''}">Inspection enregistrée</div></div><div class="tip">${b.status!=='Waste'?'En attente de la validation du responsable.':b.stage<4?'Confirmez la réception pour commencer l’inspection.':'Complétez les constats des cinq modules pour calculer les scores.'}</div><button class="primary" data-go="passport">${b.stage>=4?'Compléter l’inspection':'Voir la réception'}</button></div>`;const recorded=b.stage===5,r=recorded?b.decision.recommendation:E.recommend(decisionData(b),weights,db.markets);const currentWeights=recorded?r.weights:weights;return `<div class="grid"><section><div class="card"><span class="badge">Inspection enregistrée · ${b.id}</span><h2>Quatre orientations comparées</h2><p class="muted">Les exclusions techniques s’appliquent avant le classement.</p>${r.scores.map(s=>`<div class="actionbox score-option"><div class="scorehead"><b>${esc(orientationLabel(s.name))}</b><span>${s.eligible?s.score+' / 100':'Exclue'}</span></div><p class="orientation-description">${esc(E.orientationInfo[s.name]?.description)}</p><div class="track"><i style="width:${s.eligible?s.score:0}%"></i></div><p class="small">${s.eligible?'Compatible avec les critères de ce prototype. Prochaine action : '+esc(E.orientationInfo[s.name]?.next):'Non retenue : '+s.reasons.map(esc).join(' ')}</p><details><summary>Calcul et demande compatible</summary><p class="small">${Object.entries(s.criteria).map(([k,v])=>`${{health:'Technique',demand:'Marché',value:'Valeur',environment:'Environnement'}[k]} : ${v}/100 · contribution ${s.contributions[k]} points`).join('<br>')}</p><p class="small">${s.markets.map(esc).join(', ')||'Aucune demande compatible.'}</p></details></div>`).join('')}</div><div class="card"><h3>${recorded?'Décision validée':'Valider la décision'}</h3>${recorded?`<span class="badge">${esc(orientationLabel(b.decision.orientation))}</span><p>${esc(b.decision.justification)}</p><small class="muted">${date(b.decision.at)} · Les scores ci-dessus sont ceux enregistrés avec cette décision.</small>`:`<form id="decision"><label>Orientation retenue<select name="orientation">${r.scores.filter(s=>s.eligible).map(s=>`<option value="${s.name}">${esc(orientationLabel(s.name))}</option>`).join('')}</select></label><label>Justification<textarea name="justification" required maxlength="2000" placeholder="Expliquez votre choix…"></textarea></label><button class="primary" ${r.blocked?'disabled':''}>Valider la décision</button></form>`}</div></section><section><div class="card recommend"><div class="label">DÉFI 03 · RECOMMANDATION</div><h2>${esc(orientationLabel(r.title))}</h2><p>${esc(frenchText(r.reason))}</p><small>Validation humaine obligatoire.</small></div><div class="card"><h3>Pourquoi ce résultat ?</h3><ul class="small">${r.rules.map(rule=>`<li>${esc(frenchText(rule))}</li>`).join('')}</ul><p class="small">Seuils et notes pédagogiques à calibrer avec les professionnels.</p></div><div class="card"><h3>Pondérations</h3><form id="weights">${Object.entries(currentWeights).map(([k,v])=>`<label>${{health:'État technique',demand:'Demande du marché',value:'Valeur économique indicative',environment:'Bénéfice environnemental indicatif'}[k]}<input name="${k}" type="number" min="0" max="100" value="${v}" ${recorded?'disabled':''} required></label>`).join('')}${recorded?'':'<button class="outline">Recalculer les scores</button>'}</form></div><div class="card"><h3>Demandes du marché</h3>${(recorded?b.decision.markets:db.markets).filter(m=>m.active).map(m=>`<p><b>${esc(m.name)}</b><br><small class="muted">${esc(orientationLabel(m.orientation))} · SOH min. ${m.minSoh} % · ${m.chemistry||'Toutes chimies'}</small></p>`).join('')}</div></section></div>`;}
function selectBattery(id,newView){selected=id;if(newView)view=newView;const u=new URL(location.href);u.searchParams.set('battery',id);window.history.replaceState({},'',u);render();}
function bind(){
 if($('[data-delete]'))$('[data-delete]').onclick=openDeleteDialog;
 document.querySelectorAll('[data-id]').forEach(el=>el.onclick=()=>selectBattery(el.dataset.id,view==='inbox'?'passport':view));document.querySelectorAll('[data-review]').forEach(el=>el.onclick=()=>selectBattery(el.dataset.review,'passport'));document.querySelectorAll('[data-go]').forEach(el=>el.onclick=()=>{view=el.dataset.go;render();});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{el.disabled=true;mutate(el.dataset.action).finally(()=>{if(el.isConnected)el.disabled=false;});});
 if($('#signal'))$('#signal').onsubmit=e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;mutate('diagnostic',{note:new FormData(e.target).get('note')}).finally(()=>{if(button.isConnected)button.disabled=false;});};
 if($('#owner-decision'))$('#owner-decision').onsubmit=e=>{e.preventDefault();const action=e.submitter?.value||'waste',f=new FormData(e.target),requestId=e.target.dataset.requestId;if(action==='waste'&&!f.get('centerId'))return toast('Choisissez un centre de tri agréé avant validation.');if(action==='refuse'&&!String(f.get('refusalReason')).trim())return toast('Indiquez le motif du refus.');const buttons=e.target.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);mutate(action,{requestId,centerId:f.get('centerId'),note:f.get('refusalReason')}).finally(()=>buttons.forEach(b=>{if(b.isConnected)b.disabled=false;}));};
 if($('#legacy-transfer'))$('#legacy-transfer').onsubmit=e=>{e.preventDefault();mutate('transfer',{centerId:new FormData(e.target).get('centerId')});};
 document.querySelectorAll('[data-healthy]').forEach(el=>el.onchange=()=>{const select=$(`[name="m${el.dataset.healthy}fault"]`);if(el.checked)select.value='none';else if(select.value==='none')select.value='minor';});
 if($('#inspection'))$('#inspection').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),modules=current().modules.map((m,i)=>({healthy:f.has('m'+i+'healthy'),fault:f.get('m'+i+'fault'),visual:f.get('m'+i+'visual')}));const button=e.target.querySelector('button');button.disabled=true;mutate('inspection',{note:f.get('note'),modules}).finally(()=>{if(button.isConnected)button.disabled=false;});};
 if($('#weights'))$('#weights').onsubmit=e=>{e.preventDefault();const w=Object.fromEntries([...new FormData(e.target)].map(([k,v])=>[k,Number(v)]));try{E.recommend(decisionData(current()),w,db.markets);weights=w;render();}catch(err){toast(err.message);}};
 if($('#decision'))$('#decision').onsubmit=e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;mutate('decision',{...Object.fromEntries(new FormData(e.target)),weights}).finally(()=>{if(button.isConnected)button.disabled=false;});};
}
function login(preferredRole='mechanic',canCancel=false){const old=$('#account-dialog');if(old)old.remove();const panel=document.createElement('dialog');panel.id='account-dialog';panel.innerHTML=`<form id="login"><h2>${canCancel?'Changer de compte':'Connexion'}</h2><label>Compte<select name="username">${Object.entries(roles).map(([key,label])=>`<option value="${key}" ${key===preferredRole?'selected':''}>${label} (${key})</option>`).join('')}</select></label><label>Mot de passe<input name="password" type="password" required autocomplete="current-password"></label><p id="loginerror" role="alert"></p><div class="actions">${canCancel?'<button class="outline" type="button" id="cancel-account">Annuler</button>':''}<button class="primary" type="submit">Se connecter</button></div></form>`;document.body.append(panel);panel.addEventListener('cancel',e=>{if(!canCancel)e.preventDefault();});panel.addEventListener('close',()=>panel.remove());panel.showModal();if(canCancel)$('#cancel-account').onclick=()=>panel.close();$('#login').onsubmit=async e=>{e.preventDefault();const button=panel.querySelector('[type="submit"]');button.disabled=true;$('#loginerror').textContent='';try{const oldRole=role;await request('/api/login',Object.fromEntries(new FormData(e.target)));await loadState();if(view!=='history'&&(role!==oldRole||!canCancel))view=defaultView();panel.close();render();toast('Connecté : '+roles[role]);}catch(err){$('#loginerror').textContent=err.message;}finally{button.disabled=false;}};}
document.querySelectorAll('nav button').forEach(el=>el.onclick=()=>{view=el.dataset.view;render();});$('#role').onchange=e=>{const target=e.target.value;e.target.value=role;if(target!==role)login(target,true);};$('#search').oninput=()=>render();$('#export').onclick=async()=>{if(!db?.batteries.length)return;const b=current(),button=$('#export');button.disabled=true;try{const response=await fetch('/api/batteries/'+b.id+'/report.pdf');if(!response.ok){const data=await response.json();throw Error(data.error||'Export impossible.');}const blob=await response.blob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=b.id+'-rapport-r'+b.revision+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Rapport PDF téléchargé : état actuel du dossier.');}catch(error){toast(error.message);}finally{button.disabled=false;}};$('#scan-open').onclick=()=>openScanner();
(async()=>{try{await loadState();view=defaultView();render();}catch(e){if(e.status===401)login();else $('#content').textContent='Chargement impossible : '+e.message;}})();

function openScanner(){
 if(role==='owner')return;
 const panel=document.createElement('dialog');panel.id='scan-dialog';panel.className='scan-dialog';panel.innerHTML=`<div class="scan-heading"><h2>${role==='mechanic'?'Scanner et ajouter un passeport':'Scanner un passeport'}</h2><button type="button" class="outline" id="scan-close">Fermer</button></div><p class="small">Le QR imprimé contient les informations de la batterie. Aucun lien externe n’est ouvert.</p><div id="qr-reader"></div><p id="scan-message" class="small" role="status">Activez la caméra ou choisissez une photo du QR code.</p><div class="actions"><button class="primary" id="camera-start">Activer la caméra</button><button class="outline" id="camera-stop" hidden>Arrêter la caméra</button><label class="outline photo-label">Lire une photo<input id="qr-photo" type="file" accept="image/*"></label></div><details><summary>Coller le contenu d’un QR code</summary><textarea id="qr-text" aria-label="Contenu du QR code" placeholder="Collez ici les données du QR…"></textarea><button class="outline" id="read-qr-text">Vérifier les informations</button></details><div id="scan-result"></div>`;
 document.body.append(panel);panel.showModal();
 let reader=null,running=false,processing=false,scannedText='',closed=false,fallbackTimer=null;const message=t=>{const el=panel.querySelector('#scan-message');if(el)el.textContent=t;};
 const buttons=()=>{panel.querySelector('#camera-start').hidden=running;panel.querySelector('#camera-stop').hidden=!running;};
 async function stop(){clearTimeout(fallbackTimer);fallbackTimer=null;let scanning=running;try{scanning=scanning||reader?.getState()===2;}catch{}if(scanning){running=false;try{await reader.stop();}catch{}}if(panel.isConnected)buttons();}
 function getReader(){if(!reader){if(typeof Html5Qrcode==='undefined')throw Error('Le lecteur QR n’a pas pu être chargé. Actualisez la page.');reader=new Html5Qrcode('qr-reader',{formatsToSupport:[Html5QrcodeSupportedFormats.QR_CODE],verbose:false});}return reader;}
 async function openKnown(b){await loadState();selected=b.id;view='passport';panel.close();render();toast('Passeport déjà enregistré : fiche et statut à jour.');}
 async function decoded(raw){if(processing)return;processing=true;try{await stop();FluxQR.read(raw);message('Vérification du passeport…');const result=await request('/api/passports/lookup',{qrText:raw});if(!panel.isConnected)return;if(result.exists){await openKnown(result.battery);return;}if(role!=='mechanic')throw Error('Ce passeport n’est pas enregistré. Le mécanicien doit d’abord l’ajouter.');if(!result.passport)throw Error('Ce QR contient seulement un lien. Un QR avec les données complètes est nécessaire pour un ajout.');
  const p=result.passport;scannedText=raw;message('Nouveau passeport : vérifiez les informations avant l’ajout.');panel.querySelector('#scan-result').innerHTML=`<div class="card"><div class="label">NOUVEAU PASSEPORT · ${esc(p.id)}</div><h3>${esc(p.model)}</h3><span class="badge">En service</span><div class="facts"><div><span class="label">Série</span>${esc(p.serial)}</div><div><span class="label">Constructeur</span>${esc(p.manufacturer)}</div><div><span class="label">SOH</span>${p.soh} %</div><div><span class="label">Chimie · capacité</span>${p.chemistry} · ${p.capacity} kWh</div><div><span class="label">Âge · cycles</span>${p.age} ans · ${p.cycles} cycles</div><div><span class="label">Responsable</span>${esc(p.owner)}</div></div><details><summary>Vérifier les cinq modules</summary>${p.modules.map((m,i)=>`<p class="small">Module ${i+1} · SOH ${m.soh} % · ${m.resistance} mΩ · ${faultLabels[m.fault]}<br>${esc(m.visual)}</p>`).join('')}</details><p class="small">L’ajout enregistre les données lues. Le diagnostic et le signalement viennent ensuite.</p><button class="primary" id="confirm-import">Ajouter ce passeport</button></div>`;
  panel.querySelector('#confirm-import').onclick=async e=>{e.target.disabled=true;try{const result=await request('/api/passports/import',{qrText:scannedText});await loadState();selected=result.battery.id;view='passport';panel.close();render();toast(result.created?'Passeport ajouté au statut En service. Vous pouvez établir le diagnostic.':'Passeport déjà présent : aucun doublon créé.');}catch(err){message(err.message);if(e.target.isConnected)e.target.disabled=false;}};
 }catch(e){message(e.message||'Ce QR n’a pas pu être lu. Réessayez avec une photo nette.');}finally{processing=false;}}
 const frameCanvas=document.createElement('canvas');
 function fallbackFrame(){
  if(!running||closed||processing)return;
  const video=panel.querySelector('#qr-reader video');
  if(video?.videoWidth&&typeof FluxQRDecoder!=='undefined')try{
   const scale=Math.min(1,1600/Math.max(video.videoWidth,video.videoHeight));frameCanvas.width=Math.round(video.videoWidth*scale);frameCanvas.height=Math.round(video.videoHeight*scale);frameCanvas.getContext('2d').drawImage(video,0,0,frameCanvas.width,frameCanvas.height);
   const raw=FluxQRDecoder.decodeCanvas(frameCanvas);if(raw){decoded(raw);return;}
  }catch{}
  fallbackTimer=setTimeout(fallbackFrame,350);
 }
 let starting=false;
 panel.querySelector('#camera-start').onclick=async()=>{
  if(starting||running)return;starting=true;const button=panel.querySelector('#camera-start');button.disabled=true;
  try{
   if(!window.isSecureContext)throw Error('La caméra nécessite le lien HTTPS du site. Ouvrez le site dans Safari ou Chrome.');
   if(!navigator.mediaDevices?.getUserMedia)throw Error('Ce navigateur ne permet pas la caméra. Ouvrez le lien dans Safari ou Chrome, ou choisissez une photo.');
   panel.querySelector('#scan-result').innerHTML='';const r=getReader();
   const config={fps:8,disableFlip:false,videoConstraints:{facingMode:{ideal:'environment'},width:{ideal:1920},height:{ideal:1080}}};
   try{await r.start({facingMode:'environment'},config,raw=>decoded(raw),()=>{});}
   catch(error){
    if(['NotAllowedError','PermissionDeniedError'].includes(error?.name)||/permission|denied/i.test(String(error)))throw error;
    const cameras=await Html5Qrcode.getCameras();if(!cameras.length)throw Error('Aucune caméra détectée.');
    const rear=cameras.find(c=>/back|rear|arrière|environment/i.test(c.label))||cameras[cameras.length-1];
    await r.start(rear.id,{fps:8,disableFlip:false},raw=>decoded(raw),()=>{});
   }
   running=r.getState()===2;if(closed){await stop();return;}buttons();fallbackFrame();message('Cadrez le QR entier, avec sa bordure blanche. Ajustez la distance pour une image nette.');
  }catch(error){message(!window.isSecureContext?error.message:/permission|denied|NotAllowed/i.test(String(error))?'Accès caméra refusé. Autorisez la caméra dans les réglages du navigateur puis réessayez, ou utilisez Lire une photo.':error?.message||'Caméra indisponible. Fermez les autres applications qui l’utilisent ou choisissez une photo.');}
  finally{starting=false;if(button.isConnected)button.disabled=false;}
 };
 panel.querySelector('#camera-stop').onclick=()=>stop();panel.querySelector('#scan-close').onclick=()=>panel.close();
 panel.querySelector('#qr-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;e.target.value='';try{await stop();message('Lecture de la photo…');let raw=typeof FluxQRDecoder!=='undefined'?await FluxQRDecoder.decodeFile(file):null;try{if(!raw)raw=await getReader().scanFile(file,true);}catch(error){if(typeof BarcodeDetector!=='undefined'){const bitmap=await createImageBitmap(file);try{const codes=await new BarcodeDetector({formats:['qr_code']}).detect(bitmap);raw=codes[0]?.rawValue;}finally{bitmap.close();}}if(!raw)throw error;}await decoded(raw);}catch{message('QR non détecté sur cette image. Choisissez un PNG ou JPEG net avec le QR entier et sa bordure blanche.');}};
 panel.querySelector('#read-qr-text').onclick=()=>decoded(panel.querySelector('#qr-text').value.trim());
 panel.addEventListener('close',async()=>{closed=true;await stop();panel.remove();});
}

function openDeleteDialog(){
 if(role!=='owner')return;const b=current(),panel=document.createElement('dialog');
 panel.innerHTML=`<h2>Supprimer ${esc(b.id)} ?</h2><p>Le passeport, ses modules, ses demandes et son historique seront supprimés définitivement.</p><form id="delete-form"><label>Recopiez ${esc(b.id)} pour confirmer<input name="confirmation" autocomplete="off" required></label><p id="delete-error" role="alert"></p><div class="actions"><button type="button" class="outline" id="delete-cancel">Annuler</button><button class="primary danger-button" id="delete-confirm" disabled>Supprimer définitivement</button></div></form>`;
 document.body.append(panel);panel.showModal();panel.onclose=()=>panel.remove();panel.querySelector('#delete-cancel').onclick=()=>panel.close();
 const input=panel.querySelector('input'),button=panel.querySelector('#delete-confirm');input.oninput=()=>button.disabled=input.value!==b.id;
 panel.querySelector('form').onsubmit=async e=>{e.preventDefault();button.disabled=true;try{await request('/api/batteries/'+b.id+'/delete',{revision:b.revision,confirmation:input.value});await loadState();selected=db.batteries[0]?.id||'';view='inbox';const url=new URL(location.href);url.searchParams.delete('battery');history.replaceState(null,'',url);panel.close();render();toast('Batterie et historique supprimés.');}catch(error){panel.querySelector('#delete-error').textContent=error.message;button.disabled=input.value!==b.id;}};
}
